/* Original procedural starter sounds, CC0. No recordings or vendor sound banks. */
(()=>{const names=['Kick','Snare','Closed Hat','Open Hat','Clap','Rim','Low Tom','High Tom','Bass C','Bass Eb','Bass G','Bass Bb','Chord Cm','Pluck C','Texture','Bell C'];const kits=[{id:'house',name:'House',description:'Kick rond, hats brillants, basse et accord mineur.',bpm:124,body:1,noise:1,tone:1,decay:1},{id:'boombap',name:'Boom bap',description:'Batterie mate, clap sec et basses chaleureuses.',bpm:88,body:.85,noise:.65,tone:.7,decay:.75},{id:'electro',name:'Electro',description:'Percussions synthétiques, basse mordante et cloche FM.',bpm:128,body:1.3,noise:1.25,tone:1.4,decay:.65},{id:'ambient',name:'Ambient',description:'Percussions douces, notes longues et nappes aériennes.',bpm:80,body:.7,noise:.4,tone:.85,decay:1.6}];
function sound(id,index,rate=44100){const k=kits.find(k=>k.id===id);if(!k||!Number.isInteger(index)||index<0||index>15)throw Error('Son inconnu.');const ambient=id==='ambient',electro=id==='electro',boom=id==='boombap',seconds=index<8?(index===3?.65:.48)*k.decay:index===12?(ambient?2.6:1.4):index===14?(ambient?2:1):ambient?1.8:.9,n=Math.ceil(seconds*rate),data=new Float32Array(n);let seed=12345+index*173+Math.round(k.body*1000),phase=0,low=0,previous=0;const sine=(hz,t)=>Math.sin(2*Math.PI*hz*t),root=65.4064*Math.pow(2,[0,3,7,10][Math.max(0,Math.min(3,index-8))]/12);for(let i=0;i<n;i++){const t=i/rate;seed=(Math.imul(seed,1664525)+1013904223)>>>0;const noise=seed/2147483648-1;low+=.15*k.tone*(noise-low);const high=noise-low;let v=0;if(index===0){const hz=44*k.body+95*Math.exp(-t*(electro?52:34));phase+=2*Math.PI*hz/rate;v=(Math.sin(phase)+.08*high*Math.exp(-t*90))*Math.exp(-t*(boom?10:7)/k.decay)}else if(index===1)v=(.7*(boom?low:high)*Math.exp(-t*18/k.decay)+.25*sine(180*k.body,t)*Math.exp(-t*22));else if(index===2||index===3){const decay=(index===2?80:12)/k.decay,metal=sine(6173*k.tone,t)*sine(8231,t);v=(high*.7+metal*.3)*Math.exp(-t*decay)}else if(index===4){const bursts=[0,.012,.025,.04].reduce((sum,at)=>sum+(t>=at?Math.exp(-(t-at)*(at===.04?20:180)):0),0);v=high*bursts*.45}else if(index===5)v=(sine(820*k.tone,t)+sine(1730*k.body,t)*.4)*Math.exp(-t*90);else if(index===6||index===7){phase+=2*Math.PI*((index===6?90:145)*k.body+70*Math.exp(-t*35))/rate;v=Math.sin(phase)*Math.exp(-t*13/k.decay)}else if(index<12){const attack=Math.min(1,t/(ambient?.035:.006)),fm=electro?Math.sin(2*Math.PI*root*t+1.7*sine(root*2,t)*Math.exp(-t*5)):sine(root,t)+.22*k.tone*sine(root*2,t)+.1*k.body*sine(root*3,t);v=fm*attack*Math.exp(-t*(ambient?2.2:5))}else if(index===12){for(const semitone of [0,3,7]){const hz=130.8128*2**(semitone/12);v+=(sine(hz,t)+.25*k.tone*sine(hz*2.003,t)+.12*k.body*sine(hz*.998,t))/3}v*=Math.min(1,t/(ambient?.18:.012))*Math.exp(-t*(ambient?1:3))}else if(index===13){v=(sine(261.6256,t)+.3*sine(523.251,t)+.12*sine(1046.5,t))*Math.exp(-t*6/k.decay)}else if(index===14){v=(low*.45+sine(174.614,t)*sine(.7,t)*.3+sine(261.626,t)*.2)*Math.min(1,t/.12)*Math.exp(-t*(ambient?1.2:3))}else v=Math.sin(2*Math.PI*261.626*t+2.3*Math.exp(-t*3)*sine(261.626*2.76,t))*Math.exp(-t*3/k.decay);v*=Math.min(1,t/.0025)*Math.min(1,(n-1-i)/(rate*.025));data[i]=Number.isFinite(v)?v:0;previous=v}let peak=0;for(const v of data)peak=Math.max(peak,Math.abs(v));const level=index===2||index===3?.4:index===14?.45:index===0?.9:.72;if(peak)for(let i=0;i<n;i++)data[i]*=level/peak;return {name:k.name.toUpperCase()+' '+names[index].toUpperCase(),data,kind:index===2||index===3?'hat':index>=8&&index<12?'bass':'sound'}}
async function build(id,rate=44100){const out=[];for(let i=0;i<16;i++){out.push(sound(id,i,rate));await new Promise(resolve=>setTimeout(resolve,0))}return out}
function preview(sounds,bpm,rate=44100){const dt=60/bpm/4,duration=dt*32+1.3,mix=new Float32Array(Math.ceil(duration*rate));for(let step=0;step<32;step++){const hits=[];if(step%4===0)hits.push(0);if(step%8===4)hits.push(1);if(step%2===0)hits.push(2);if(step%16===14)hits.push(3);if([0,6,8,11].includes(step%16))hits.push(8+([0,0,2,1][Math.floor(step/8)]));if(step%16===0)hits.push(12);if(step%8===7)hits.push(15);for(const index of hits){const start=Math.round(step*dt*rate),d=sounds[index].data;for(let i=0;i<d.length&&start+i<mix.length;i++)mix[start+i]+=d[i]*(index>=8?.22:.5)}}let peak=1;for(const v of mix)peak=Math.max(peak,Math.abs(v));for(let i=0;i<mix.length;i++)mix[i]*=.8/peak;return mix}
globalThis.PocketStarter={kits,names,sound,build,preview};})();
